import { describe, it, expect } from 'vitest';
import { normalise } from '../src/text.js';

const only = (xs) => xs.filter(Boolean);
const matcher = { only: true };

describe('normalise', () => {
  it('collapses runs of whitespace', () => {
    expect(normalise('a   b')).toBe('a b');
    expect(only([null, 'a'])).toStrictEqual(['a']);
    expect(matcher.only).toBe(true);
  });
});
